#include <stdio.h>

int main() {
    int rolls[8] = {3, 8, 12, 17, 21, 26, 30, 35};
    int n = 8;
    int target = 26;

    /* Linear search */
    int found = -1;
    for (int i = 0; i < n; i++) {
        if (rolls[i] == target) {
            found = i;
            break;
        }
    }
    printf("Linear: found at index %d\n", found);

    /* Binary search (array must be sorted) */
    int low = 0, high = n - 1, pos = -1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (rolls[mid] == target) {
            pos = mid;
            break;
        } else if (rolls[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    printf("Binary: found at index %d\n", pos);
    return 0;
}

